import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Img,
} from '../remotionShim';
// Fonts
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const { fontFamily: interFamily } = loadInter();



export type ChecklistAnimationProps = Record<string, any>;

const AuraBackground: React.FC<{ accentColor: string }> = ({ accentColor }) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const pulse1 = interpolate(frame, [15, 25, 45], [0, 0.4, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const pulse2 = interpolate(frame, [35, 45, 65], [0, 0.4, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const pulse3 = interpolate(frame, [55, 65, 85], [0, 0.4, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const basePulse = interpolate(Math.sin(frame / 15), [-1, 1], [0.1, 0.2]);
  const dynamicOpacity = basePulse + pulse1 + pulse2 + pulse3;

  return (
    <AbsoluteFill
      style={{
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden",
      }}
    >
      <div
        style={{
          position: "absolute",
          top: height * 0.1,
          left: -width * 0.5,
          width: width * 1.5,
          height: width * 1.5,
          background: `radial-gradient(circle, ${accentColor} 0%, transparent 60%)`,
          opacity: dynamicOpacity,
          filter: "blur(100px)",
          transition: "none",
        }}
      />
      <div
        style={{
          position: "absolute",
          bottom: -height * 0.2,
          right: -width * 0.5,
          width: width * 1.5,
          height: width * 1.5,
          background: `radial-gradient(circle, ${accentColor} 0%, transparent 60%)`,
          opacity: dynamicOpacity * 0.8,
          filter: "blur(100px)",
          transition: "none",
        }}
      />
    </AbsoluteFill>
  );
};

const CheckItem: React.FC<{
  text: string;
  index: number;
  accentColor: string;
}> = ({ text, index, accentColor }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Shifted start frame by 12 frames to account for the initial background blur sequence
  const startFrame = 30 + index * 30;
  const delayFrame = Math.max(0, frame - startFrame);

  // Slowed Slide & Fade
  const slideProgress = spring({
    fps,
    frame: delayFrame,
    config: { damping: 30, mass: 1.8 },
  });
  const xOffset = interpolate(slideProgress, [0, 1], [-100, 0]);
  const opacity = interpolate(delayFrame, [0, 23], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Slowed SVG Tick
  const tickDelay = Math.max(0, delayFrame - 12);
  const tickProgress = spring({
    fps,
    frame: tickDelay,
    config: { damping: 27, mass: 1.5 },
  });
  const strokeDashoffset = interpolate(tickProgress, [0, 1], [24, 0]);

  // Slowed Glow Burst
  const burstDelay = Math.max(0, delayFrame - 14);
  const burstScale = interpolate(burstDelay, [0, 30], [0.5, 2.5], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const burstOpacity = interpolate(burstDelay, [0, 12, 36], [0, 0.8, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        opacity,
        transform: `translateX(${xOffset}px)`,
        marginBottom: 110,
        position: "relative",
        transition: "none",
      }}
    >
      <div
        style={{
          width: 120,
          height: 120,
          position: "relative",
          marginRight: 70,
          flexShrink: 0,
        }}
      >
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: accentColor,
            borderRadius: "50%",
            transform: `scale(${burstScale})`,
            opacity: burstOpacity,
            filter: "blur(10px)",
            transition: "none",
          }}
        />
        <svg
          viewBox="0 0 24 24"
          style={{
            width: "100%",
            height: "100%",
            position: "relative",
            zIndex: 2,
            filter: `drop-shadow(0 0 12px ${accentColor})`,
          }}
        >
          <path
            d="M20 6L9 17l-5-5"
            fill="none"
            stroke={accentColor}
            strokeWidth="3"
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeDasharray={24}
            strokeDashoffset={strokeDashoffset}
          />
        </svg>
      </div>
      <div
        style={{
          fontSize: 120,
          color: "#FFFFFF",
          fontWeight: 600,
          letterSpacing: "-0.02em",
          lineHeight: 1.1,
          textShadow: "0px 8px 20px rgba(0,0,0,0.5)",
        }}
      >
        {text}
      </div>
    </div>
  );
};

const ChecklistAnimation: React.FC<ChecklistAnimationProps> = ({
  backgroundImage = "https://images.unsplash.com/photo-1550684848-fac1c5b4e853?q=80&w=1080&auto=format&fit=crop",
  backgroundColor = "#050A18",
  transparentBackground = false,
  durationInSeconds = 3,
  title = "Built with intention.",
  titleFontSize = 130,
  items = ["Flexibility", "Structure", "Real Growth"],
  accentColor = "#00C6FF",
}) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const durationInFrames = Math.round(durationInSeconds * fps);

  // Background Image Bokeh & Blur Sequence
  const imageBlur = interpolate(frame, [0, 12], [0, 24], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  
  // Scale starts at 1.1 to avoid edge bleed when blurring
  const imageScale = interpolate(frame, [0, durationInFrames], [1.1, 1.25], {
    extrapolateRight: "clamp",
  });

  const overlayOpacity = interpolate(frame, [0, 12], [0, 0.4], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  // Global Camera Micro-Zoom
  const globalZoom = interpolate(frame, [0, durationInFrames], [1, 1.05], {
    extrapolateRight: "clamp",
  });

  // End Fade
  const fadeOutStart = durationInFrames - 10;
  const globalOpacity = interpolate(
    frame,
    [fadeOutStart, durationInFrames],
    [1, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Title Animations (Shifted later to allow blur to finish)
  const titleDelayFrame = Math.max(0, frame - 12);
  const titleProgress = spring({
    fps,
    frame: titleDelayFrame,
    config: { damping: 15, mass: 0.75 },
  });
  const titleScale = interpolate(titleProgress, [0, 1], [0.8, 1]);
  const titleInOpacity = interpolate(frame, [12, 18], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const titleOutOpacity = interpolate(frame, [24, 30], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const titleY = interpolate(frame, [24, 30], [0, -40], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const activeTitleOpacity = frame > 24 ? titleOutOpacity : titleInOpacity;

  // Checklist Track Animation (Shifted later)
  const listDelay = Math.max(0, frame - 30);
  const trackProgress = spring({
    fps,
    frame: listDelay,
    config: { damping: 36, mass: 2.3 }, 
  });
  const trackHeight = interpolate(trackProgress, [0, 1], [0, 100]);
  const trackOpacity = interpolate(listDelay, [0, 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        transition: "none",
        overflow: "hidden",
      }}
    >
      {backgroundImage && !transparentBackground && (
        <AbsoluteFill>
          <Img
            src={backgroundImage}
            style={{
              width: "100%",
              height: "100%",
              objectFit: "cover",
              filter: `blur(${imageBlur}px)`,
              transform: `scale(${imageScale})`,
              transition: "none",
            }}
          />
          <div
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              backgroundColor: "#000000",
              opacity: overlayOpacity,
              transition: "none",
            }}
          />
        </AbsoluteFill>
      )}

      <AuraBackground accentColor={accentColor} />

      <div
        style={{
          width: "100%",
          height: "100%",
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "center",
          transform: `scale(${globalZoom})`,
          opacity: globalOpacity,
          position: "relative",
          zIndex: 10,
          transition: "none",
        }}
      >
        {/* Title */}
        {activeTitleOpacity > 0 && (
          <div
            style={{
              position: "absolute",
              top: "35%",
              left: 0,
              right: 0,
              textAlign: "center",
              opacity: activeTitleOpacity,
              transform: `translateY(${titleY}px) scale(${titleScale})`,
              fontSize: titleFontSize,
              fontWeight: 700,
              color: "#FFFFFF",
              letterSpacing: "-0.03em",
              transition: "none",
            }}
          >
            {title}
          </div>
        )}

        {/* Checklist Block */}
        {frame > 29 && (
          <div
            style={{
              width: "100%",
              maxWidth: width * 0.90,
              position: "relative",
              paddingTop: 80,
            }}
          >
            <div
              style={{
                position: "absolute",
                left: 59,
                top: 100,
                bottom: 110,
                width: 2,
                opacity: trackOpacity,
                transition: "none",
              }}
            >
              <div
                style={{
                  width: "100%",
                  height: `${trackHeight}%`,
                  backgroundColor: accentColor,
                  boxShadow: `0 0 12px ${accentColor}, 0 0 24px ${accentColor}`,
                  transition: "none",
                }}
              />
            </div>

            <div style={{ position: "relative", zIndex: 1 }}>
              {items.map((item, i) => (
                <CheckItem
                  key={i}
                  text={item}
                  index={i}
                  accentColor={accentColor}
                />
              ))}
            </div>
          </div>
        )}
      </div>
    </AbsoluteFill>
  );
};

export default ChecklistAnimation;